import { AlgoKey } from '../../../shared/prediction.types';
import { AlgorithmPlugin } from '../algorithmRegistry';

export const temporalPlugin: AlgorithmPlugin = {
  key: AlgoKey.TEMPORAL,
  category: 'advanced',
  stability: 'stable',
  mathematicalBasis: 'Fusion de Modèle Temporel Continu et de Loi de Poisson',
  description: 'Modèle temporel unifié combinant les tendances temporelles profondes et d\'espérance mathématique de Poisson.',
  isStrictlyDeterministic: true,
    // @ts-ignore - auto generated by cleanup
  precompute(ctx) {},
  evaluate(num, ctx) {
    const tempVal = (ctx.advancedMetrics?.temporal as Record<number, number>)?.[num] || 0.0;
    const poissonVal = (ctx.advancedMetrics?.poisson as Record<number, number>)?.[num] || 0.0;
    
    // Fusion continue (combinaison par moyenne géométrique douce)
    const fusedVal = Math.sqrt(tempVal * poissonVal) || (tempVal + poissonVal) / 2.0;
    const score = Math.max(0.0, Math.min(100.0, fusedVal));
    return {
      score,
      confidence: 0.95,
      metadata: { tempVal, poissonVal }
    };
  }
};

export const bayesPlugin: AlgorithmPlugin = {
  key: AlgoKey.BAYES,
  category: 'core',
  stability: 'stable',
  mathematicalBasis: 'Inférence Bayesienne et Probabilité Conditionnelle Continue (Modulée par l\'Intuition du Meta LLM)',
  description: 'Évalue les probabilités a posteriori bayésiennes pour chaque numéro avec un ajustement d\'ensemble LLM.',
  isStrictlyDeterministic: true,
    // @ts-ignore - auto generated by cleanup
  precompute(ctx) {},
  evaluate(num, ctx) {
    const bayesVal = (ctx.advancedMetrics?.bayes as Record<number, number>)?.[num] || 0.0;
    
    // Modulation par Intuition de l'Ensemble Pédagogique (LLM) structuré sur des features complexes
    const aiVal = (ctx.advancedMetrics?.aiIntuition as Record<number, number>)?.[num] || 0.0;
    
    const fusedVal = bayesVal * (1.0 + aiVal / 100.0);
    const score = Math.max(0.0, Math.min(100.0, fusedVal));
    return {
      score,
      confidence: 0.95,
      metadata: { bayesVal, aiVal }
    };
  }
};
